+  "test_source": "import importlib\nimport math\nimport pathlib\nimport sys\nimport unittest\nfrom types import SimpleNamespace\n\nimport torch\n\n# Import the frozen candidate directly from its source tree, independent of cwd.\nROOT = pathlib.Path(__file__).resolve().parents[5] / \"stage2_RQ-VAE\" / \"TIGER_c117_global_sinkhorn_poincare\"\nif str(ROOT) not in sys.path:\n    sys.path.insert(0, str(ROOT))\nhyperbolic = importlib.import_module(\"model.hyperbolic\")\nmodel_module = importlib.import_module(\"model.model\")\n\n\ndef independent_poincare_squared(x, y, c=1.0):\n    if c == 0.0:\n        return 4.0 * ((x - y) ** 2).sum(dim=-1)\n    delta2 = ((x - y) ** 2).sum(dim=-1)\n    denom = (1.0 - c * (x * x).sum(dim=-1)) * (1.0 - c * (y * y).sum(dim=-1))\n    arg = 1.0 + 2.0 * c * delta2 / denom\n    # Independent stable identity for acosh, evaluated away from coincidence.\n    a = torch.log(arg + torch.sqrt(arg * arg - 1.0))\n    return a.square() / c\n\n\nclass TestGeometryGradient(unittest.TestCase):\n    def test_distance_matches_independent_oracle_and_gradcheck(self):\n        torch.manual_seed(17)\n        x = (torch.randn(2, 3, dtype=torch.double) * 0.12).requires_grad_()\n        y = (torch.randn(2, 3, dtype=torch.double) * 0.12).requires_grad_()\n        actual = hyperbolic.squared_distance(x, y, c=1.0)\n        expected = independent_poincare_squared(x, y, c=1.0)\n        self.assertTrue(torch.allclose(actual, expected, rtol=1e-9, atol=1e-11))\n        self.assertTrue(torch.autograd.gradcheck(\n            lambda a, b: hyperbolic.squared_distance(a, b, c=1.0),\n            (x, y), eps=1e-6, atol=2e-5, rtol=2e-4))\n        gx, gy = torch.autograd.grad(actual.sum(), (x, y))\n        self.assertTrue(torch.isfinite(gx).all().item())\n        self.assertTrue(torch.isfinite(gy).all().item())\n        self.assertGreater(gx.norm().item(), 1e-7)\n        self.assertGreater(gy.norm().item(), 1e-7)\n\n    def test_flat_limit_and_projection_gradient(self):\n        x = torch.tensor([[0.2, -0.1], [0.8, 0.3]], dtype=torch.double, requires_grad=True)\n        y = torch.tensor([[-0.1, 0.4], [0.1, -0.2]], dtype=torch.double, requires_grad=True)\n        flat = hyperbolic.squared_distance(x, y, c=0.0)\n        self.assertTrue(torch.allclose(flat, independent_poincare_squared(x, y, 0.0)))\n        projected = hyperbolic.project_ball(x, radius=0.9)\n        self.assertTrue(torch.all(torch.linalg.vector_norm(projected, dim=-1) <= 0.9 + 1e-12).item())\n        loss = hyperbolic.squared_distance(projected, y, c=0.0).sum()\n        loss.backward()\n        self.assertIsNotNone(x.grad)\n        self.assertGreater(x.grad.norm().item(), 1e-7)\n        self.assertTrue(torch.isfinite(x.grad).all().item())\n\n\nclass TestActualTrainingLossGradient(unittest.TestCase):\n    @staticmethod\n    def make_model():\n        cfg = SimpleNamespace(hidden_sizes=[5], dropout=0.0, codebook_num=2,\n                              codebook_size=[3, 3], codebook_dim=2, curvature=1.0, radius=0.9)\n        net = model_module.RQVAE(cfg, in_dim=4).double()\n        with torch.no_grad():\n            # Deterministic non-degenerate encoder and code vectors.\n            first = net.encoder.mlp[1]\n            first.weight.copy_(torch.tensor([[.2,.1,.3,.1], [.1,.3,.1,.2],\n                                             [.3,.2,.1,.1], [.1,.2,.3,.2],\n                                             [.2,.3,.2,.1]], dtype=torch.double))\n            first.bias.fill_(0.15)\n            out = net.encoder.mlp[3]\n            out.weight.copy_(torch.tensor([[.2,.1,.3,.2,.1], [.1,.3,.2,.1,.2]], dtype=torch.double))\n            out.bias.copy_(torch.tensor([.1,.2], dtype=torch.double))\n            for level, codebook in enumerate(net.rq.codebooks):\n                codebook.copy_(torch.tensor([[-.35,-.15], [.05,.3], [.4,-.1]], dtype=torch.double) + level * .025)\n        return net\n\n    def test_real_model_loss_reaches_encoder_and_each_codebook(self):\n        torch.manual_seed(5)\n        net = self.make_model()\n        embeddings = torch.tensor([[1.,.2,.1,.3], [.2,1.,.4,.1], [.1,.3,1.,.2],\n                                   [.4,.1,.2,1.], [1.,.5,.2,.1], [.3,.2,.5,1.]], dtype=torch.double)\n        net.refresh_assignment(embeddings)\n        self.assertFalse(net.frozen_reconstruction.requires_grad)\n        self.assertFalse(net.frozen_codes.requires_grad)\n        total, rec, bal = net(embeddings, torch.arange(len(embeddings)))\n        self.assertTrue(torch.isfinite(total).item())\n        self.assertTrue(torch.isfinite(rec).item())\n        self.assertTrue(torch.isfinite(bal).item())\n        self.assertGreater(total.item(), 0.0)\n        total.backward()\n        encoder_grad = net.encoder.mlp[1].weight.grad\n        self.assertIsNotNone(encoder_grad)\n        self.assertTrue(torch.isfinite(encoder_grad).all().item())\n        self.assertGreater(encoder_grad.norm().item(), 1e-8)\n        for i, codebook in enumerate(net.rq.codebooks):\n            self.assertIsNotNone(codebook.grad, f\"codebook {i} disconnected\")\n            self.assertTrue(torch.isfinite(codebook.grad).all().item())\n            self.assertGreater(codebook.grad.norm().item(), 1e-8, f\"codebook {i} has no useful gradient\")\n\n    def test_nonfinite_and_detached_graph_controls_are_detected(self):\n        # Negative controls demonstrate that the finite/connected checks above\n        # would reject NaNs and a detached objective rather than passing vacuously.\n        nan_loss = torch.tensor(float('nan'), requires_grad=True)\n        self.assertFalse(torch.isfinite(nan_loss).item())\n        source = torch.tensor([2.0], requires_grad=True)\n        disconnected = source.detach().square().sum()\n        self.assertFalse(disconnected.requires_grad)\n        self.assertFalse(disconnected.grad_fn is not None)\n        with self.assertRaises(RuntimeError):\n            disconnected.backward()\n\n\nif __name__ == '__main__':\n    unittest.main()\n"
